type TaskRow = readonly [string, string, string];
type TaskGuide = {
  intro: string;
  example: string;
  dutyRows: readonly TaskRow[];
  sizingRows: readonly TaskRow[];
  configurationRows: readonly TaskRow[];
  cycle: readonly string[];
  faultRows: readonly TaskRow[];
  acceptanceRows: readonly TaskRow[];
  external: ApplicationReference;
  foreach: ApplicationReference;
  productLink: ApplicationLink;
  related: readonly string[];
};

type GroupGuide = {
  intro: string;
  boundary: string;
  flow: readonly string[];
  selectionRows: readonly TaskRow[];
  inputs: readonly TaskRow[];
  external: ApplicationReference;
  foreach: ApplicationReference;
  productLink: ApplicationLink;
  tasks: readonly string[];
};

