function taskLinks(slugs: readonly string[]) {
  return slugs.map((slug) => {
    const label = getAnalyticalDocumentMetadata(slug)?.navLabel ?? slug;
    return { label, href: analyticalDocumentHref(slug) };
  });
}

function makeGroupBody(group: GroupGuide): ApplicationDocumentBody {
  return {
    intro: [{ type: "paragraph", text: group.intro }, { type: "paragraph", text: group.boundary, references: [group.external.id, group.foreach.id] }],
    sections: [
      { id: "fluid-path-role", title: "Place the component in the complete analytical fluid path", blocks: [
        { type: "flow", caption: "Functional relationship, not a mandatory installation order", nodes: group.flow, focusIndex: 2 },
        { type: "paragraph", text: "Draw the liquid path for prime, normal operation, wash, idle and recovery. Mark which liquid contacts each part and where volume, concentration, pressure or detector response will be accepted." },
      ] },
      { id: "selection-boundaries", title: "Select by operating duty rather than a family name", blocks: [
        { type: "table", caption: "Configuration decisions that separate the available routes", headers: ["Configuration", "Best starting duty", "Boundary to confirm"], rows: group.selectionRows },
        { type: "callout", title: "Published values require context", text: "Capacity, displacement, free flow, rated pressure and interface size describe different limits. Do not combine them into one unsupported operating point. Confirm performance at the actual liquid, load, speed and sequence." },
      ] },
      { id: "task-guides", title: "Continue with the application task that matches the liquid movement", blocks: [
        { type: "links", items: taskLinks(group.tasks) },
        { type: "paragraph", text: "Each task guide uses a concrete liquid path, calculation, abnormal-condition table and receiving-position acceptance plan. Choose by what the instrument must accomplish, not by a broad market label." },
      ] },
      { id: "configuration-inputs", title: "Provide the inputs that change the configuration", blocks: [
        { type: "table", caption: "Information needed before a prototype configuration can be judged", headers: ["Input", "Provide", "Why it changes the design"], rows: group.inputs },
        { type: "paragraph", text: "FOREACH can use these inputs to match the product configuration, wetted materials, interfaces and control arrangement. The instrument developer remains responsible for method limits, safety logic and qualification of the complete analyzer." },
      ] },
      { id: "verification-plan", title: "Verify the result after priming, idle time and a realistic fault", blocks: [
        { type: "list", ordered: true, items: ["Record the installed configuration and actual liquid, not only the component model.", "Measure steady operation and the first cycle after priming, planned idle and liquid replacement.", "Challenge the relevant abnormal condition: air entry, restriction, low level, blocked outlet or incomplete wash.", "Accept the result at the receiving vessel, detector or cleaned surface; retain the component-level signal for diagnosis."] },
        { type: "links", items: [group.productLink, { label: "Discuss an analytical-instrument fluid path", href: "/en/contact/" }] },
      ] },
    ],
    references: [group.external, group.foreach],
    related: taskLinks(group.tasks),
  };
}

