function makeTaskBody(guide: TaskGuide): ApplicationDocumentBody {
  return {
    intro: [
      { type: "paragraph", text: guide.intro },
      { type: "paragraph", text: guide.example, references: [guide.external.id, guide.foreach.id] },
    ],
    sections: [
      { id: "define-duty", title: "Define the liquid, receiver and complete duty before selecting the component", blocks: [
        { type: "table", caption: "Translate the analytical task into an engineering duty", headers: ["Use case", "Inputs to define", "Decision supported"], rows: guide.dutyRows },
        { type: "callout", title: "Keep published examples inside their boundary", text: "The referenced international-manufacturer workflow explains how a mature instrument organizes this task. It does not transfer that manufacturer's specifications to a FOREACH component. FOREACH capability is stated only through the cited product information and must be confirmed at the selected working point." },
      ] },
      { id: "working-point", title: "Calculate the working point and the margin the instrument really needs", blocks: [
        { type: "table", caption: "Calculations to complete before prototype selection", headers: ["Quantity", "How to define it", "Why it matters"], rows: guide.sizingRows },
        { type: "paragraph", text: "Use minimum, routine and maximum conditions rather than one nominal point. Include the first cycle after priming or idle, the lowest source level, the highest expected restriction and the actual receiving geometry. A nominal capacity, free-flow value or theoretical command increment is not an acceptance result." },
      ] },
      { id: "foreach-configuration", title: "Map the task to a FOREACH configuration and the rest of the fluid path", blocks: [
        { type: "table", caption: "Configuration routes to compare", headers: ["Configuration", "When it is a useful starting point", "Boundary to confirm"], rows: guide.configurationRows, references: [guide.foreach.id] },
        { type: "links", items: [guide.productLink, { label: "Discuss this analytical-instrument duty with FOREACH", href: "/en/contact/" }] },
      ] },
      { id: "complete-cycle", title: "Program the full liquid cycle, including prime, wash and recovery", blocks: [
        { type: "flow", caption: "A complete method cycle is more than the active delivery step", nodes: guide.cycle, focusIndex: 2, note: "The exact physical order and parallel actions depend on the instrument. Retain each state in the control and verification plan." },
        { type: "paragraph", text: "Record valve states, motion, dwell, sensor windows and rejected recovery cycles. This makes throughput and liquid consumption auditable and prevents a fast component movement from being reported as the complete analyzer cycle." },
      ] },
      { id: "fault-diagnosis", title: "Design abnormal-state diagnosis before the fault occurs", blocks: [
        { type: "table", caption: "Observed result, likely mechanism and useful next action", headers: ["Observed condition", "Likely mechanism", "Engineering response"], rows: guide.faultRows },
        { type: "paragraph", text: "The controller should distinguish a recoverable event from a result-invalidating event. A retry is useful only after the original cause has been removed and the liquid path has returned to a verified state." },
      ] },
      { id: "receiving-position-verification", title: "Accept performance where the liquid is actually used", blocks: [
        { type: "table", caption: "Minimum qualification plan for the integrated channel", headers: ["Result", "Where or how to measure", "Acceptance question"], rows: guide.acceptanceRows },
        { type: "list", ordered: true, items: ["Test the exact liquid and complete wetted path at minimum, routine and maximum conditions.", "Separate first-cycle, steady-state and post-idle results; do not average away recovery behavior.", "Challenge the relevant fault and confirm the controller prevents an invalid result from being accepted.", "Retain the configuration, software sequence, consumables and receiving-position result together as the qualification record."] },
      ] },
    ],
    references: [guide.external, guide.foreach],
    related: guide.related.map((slug) => ({ label: getAnalyticalDocumentMetadata(slug)?.navLabel ?? slug, href: analyticalDocumentHref(slug) })),
  };
}

export const additionalAnalyticalBodies = {
  ...Object.fromEntries(Object.entries(groupGuides).map(([slug, guide]) => [slug, makeGroupBody(guide)])),
  ...Object.fromEntries(Object.entries(taskGuides).map(([slug, guide]) => [slug, makeTaskBody(guide)])),
} as Record<string, ApplicationDocumentBody>;
